from dataclasses import dataclass


@dataclass
class Transaction:
    title: str
    amount: float


def summary(items):
    transactions = [Transaction(title, amount) for title, amount in items]
    if not transactions:
        return [0, None]
    biggest = max(transactions, key=lambda t: abs(t.amount))
    return [sum(t.amount for t in transactions), biggest.title]

